def _checkpoint_resume_transition(status: str, action: str) -> str | None:
    """Describe whether a persisted checkpoint status can enter resume."""
    if action == "resume" and status != "completed":
        return "resumable"
    if status == "completed" and action == "resume":
        return "closed"
    return None

